/**
 * List pull requests in GitHub repositories within a time window. Use this to:
 * - Find recently merged PRs to understand recent changes
 * - Review what work has been completed in a given period
 * - Track PR activity for specific repositories
 * - Understand the development history and velocity
 *
 * The tool returns PR details including title, description, author, merge status, and dates.
 * Dates are specified in YYYY-MM-DD format (e.g., "2024-01-15"). The since date is interpreted as the start of that day (00:00:00), and the until date is interpreted as the end of that day (23:59:59).
 */
export interface ListGitHubPullRequestsParams {
    /**
     * Repository in "owner/repo" format (e.g., "facebook/react"). Must be one of the configured repositories.
     */
    repository: string
    /**
     * Filter by PR state. Use "closed" to see merged PRs, "open" for in-progress, or "all" for both.
     */
    state: "open" | "closed" | "all"
    /**
     * Start date in YYYY-MM-DD format (e.g., "2024-01-15"). Only PRs updated on or after this date (starting at 00:00:00) are included. Use null for no start filter.
     */
    since: string | null
    /**
     * End date in YYYY-MM-DD format (e.g., "2024-01-15"). Only PRs updated on or before this date (ending at 23:59:59) are included. Use null for no end filter.
     */
    until: string | null
    /**
     * Number of results to return (default: 20, max: 100)
     */
    perPage: number
    /**
     * Page number for pagination (default: 1). Use this to fetch additional PRs if there are more than perPage results. Use null for page 1. Must be a positive integer >= 1.
     */
    page: number | null
}

