/**
 * Summarize the diff of a pull request from a GitHub repository using an intelligent sub-agent. Use this to:
 * - Understand what changes were made in a specific PR without loading the full diff into context
 * - Get a concise summary of code changes before merging
 * - Analyze the impact of a PR on the codebase efficiently
 * - See file-by-file changes with key insights
 *
 * The tool launches a sub-agent that:
 * - Reads the full PR diff from GitHub
 * - Analyzes the changes using a compact model
 * - Provides a structured summary including:
 *   - Overview of changes
 *   - Key files modified
 *   - Notable additions/removals
 *   - Impact assessment
 *
 * You can optionally provide high-level context about what you're looking for in the PR, which will help the sub-agent focus its analysis.
 */
export interface SummarizeGitHubPullRequestDiffParams {
    /**
     * The repository in "owner/repo" format (e.g., "facebook/react"). Must be one of the configured repositories.
     */
    repository: string
    /**
     * The pull request number (e.g., 123 for PR #123)
     */
    pullNumber: number
    /**
     * Page number for pagination (default: 1). Use this to fetch additional files if a PR has more than 100 files. Use null for page 1. Must be a positive integer >= 1.
     */
    page: number | null
    /**
     * Optional high-level context about what you're looking for in this PR. This helps the sub-agent focus its analysis. For example: "I need to understand the authentication changes" or "Focus on database migration changes". Use null if no specific context.
     */
    context: string | null
}

export interface SummarizeGitHubPullRequestDiffResult {
    success: boolean
    actions?: RunHistoryAction[]
    repository: string
    pullRequest: {
        number: number
        title: string
        state: string
        merged: boolean
        baseBranch: string
        headBranch: string
        url: string
    }
    summary: {
        [k: string]: unknown
    }
    pagination: {
        page: number
        perPage: number
        hasMore: boolean
    }
    analysis: string
    message: string
}

