/**
 * Send message to a Slack channel or DM. Provide channelId (C…/G…/D…) or slackUserId (U…) to open or reuse a 1:1 DM. Supports plain text (mrkdwn) or Block Kit (JSON blocks). If both are set, channelId is used.
 */
export interface SlackSendMessageParams {
    /**
     * Slack channel ID (C…/G…) or existing DM channel ID (D…). Omit when sending via slackUserId (opens DM if needed).
     */
    channelId?: string | null
    /**
     * Slack member ID (U…) to send a direct message. The workspace opens the DM conversation if one does not exist yet. Omit when sending to channelId.
     */
    slackUserId?: string | null
    /**
     * Message content (mrkdwn). Used as fallback for Block Kit or main message.
     */
    message: string
    /**
     * Thread timestamp to reply to existing thread. If sending a message to a thread, this should be the timestamp of the thread to reply to. If sending an unthreaded message, this should be set to null.
     */
    thread_ts?: string | null
    /**
     * Block Kit JSON array string for interactive messages with buttons, structured layouts
     */
    blocks?: string | null
}

